const meta = $('Project Input').first().json;
const r = $input.first().json || {};
const hdr = r.headers || {};
const total = parseInt(hdr['x-pagination-total-count'] || '0', 10);
const MAX_PAGES = 40;
let pages = Math.ceil(total / 5000);
let capped = false;
if (pages > MAX_PAGES) { pages = MAX_PAGES; capped = true; }
const out = [];
for (let p = 2; p <= pages; p++) {
  out.push({ json: { page: p, capped: capped, noop: false, url: 'https://api.lokalise.com/api2/projects/' + meta.project_id + '/keys?limit=5000&page=' + p + '&disable_references=1&filter_archived=exclude' } });
}
if (out.length === 0) {
  out.push({ json: { page: 0, capped: false, noop: true, url: 'https://api.lokalise.com/api2/projects/' + meta.project_id + '/keys?limit=1&page=1&disable_references=1' } });
}
return out;

const meta = $('Project Input').first().json;
const since = parseInt(meta.since_ts, 10) || 0;
const CHUNK = 150;
const MAX_KEYS = 15000;
const pageMeta = $('Build Key Pages').all();
let noopPages = false;
if (pageMeta.length === 1 && pageMeta[0].json.noop) { noopPages = true; }
let capped = false;
for (const p of pageMeta) { if (p.json.capped) { capped = true; } }

const first = $('Fetch Key Page 1').first().json || {};
let failed = false;
if (first.statusCode !== 200) { failed = true; }
const batches = [];
batches.push((first.body || {}).keys || []);
if (!noopPages) {
  for (const it of $input.all()) {
    const j = it.json || {};
    if (j.statusCode !== 200) { failed = true; continue; }
    batches.push((j.body || {}).keys || []);
  }
}

const changed = [];
let scanned = 0;
for (const arr of batches) {
  for (const k of arr) {
    scanned++;
    if (k.is_archived) { continue; }
    const ts = k.translations_modified_at_timestamp || 0;
    if (ts >= since) { changed.push(k.key_id); }
  }
}
if (changed.length > MAX_KEYS) { changed.length = MAX_KEYS; capped = true; }

const out = [];
for (let i = 0; i < changed.length; i += CHUNK) {
  const ids = changed.slice(i, i + CHUNK);
  out.push({ json: {
    noop: false,
    candidates: changed.length,
    keys_scanned: scanned,
    failed: failed,
    capped: capped,
    chunk_size: ids.length,
    url: 'https://api.lokalise.com/api2/projects/' + meta.project_id + '/keys?limit=500&page=1&disable_references=1&include_translations=1&filter_key_ids=' + ids.join(',')
  }});
}
if (out.length === 0) {
  out.push({ json: { noop: true, candidates: 0, keys_scanned: scanned, failed: failed, capped: capped, chunk_size: 0, url: 'https://api.lokalise.com/api2/projects/' + meta.project_id + '/keys?limit=1&page=1&disable_references=1' } });
}
return out;

const meta = $('Project Input').first().json;
const since = parseInt(meta.since_ts, 10) || 0;
const base = String(meta.base_lang || 'en').toLowerCase();
const exclRaw = String(meta.exclude_emails || '').toLowerCase();
const excl = [];
for (const e of exclRaw.split(',')) { const v = e.trim(); if (v) { excl.push(v); } }

const chunkMeta = $('Find Changed Keys').all();
const m0 = chunkMeta[0].json;
let failed = m0.failed;
let capped = m0.capped;
const candidates = m0.candidates;
const keysScanned = m0.keys_scanned;
const noop = m0.noop;

function isPseudo(iso) { const s = (iso || '').toLowerCase(); return s === 'pst' || s.indexOf('pseudo') >= 0; }

const byLang = {};
const allKeys = {};
const editors = {};
let detailKeys = 0;
if (!noop) {
  for (const it of $input.all()) {
    const j = it.json || {};
    if (j.statusCode !== 200) { failed = true; continue; }
    for (const k of ((j.body || {}).keys || [])) {
      detailKeys++;
      if (k.is_archived) { continue; }
      for (const t of (k.translations || [])) {
        const ts = t.modified_at_timestamp || 0;
        if (ts < since) { continue; }
        if (t.is_untranslated) { continue; }
        const iso = String(t.language_iso || '').toLowerCase();
        if (iso === base) { continue; }
        if (isPseudo(iso)) { continue; }
        const em = String(t.modified_by_email || ('id:' + t.modified_by)).toLowerCase();
        if (excl.indexOf(em) >= 0) { continue; }
        if (!byLang[iso]) { byLang[iso] = {}; }
        byLang[iso][k.key_id] = 1;
        allKeys[k.key_id] = 1;
        editors[em] = (editors[em] || 0) + 1;
      }
    }
  }
}

const counts = {};
for (const l of Object.keys(byLang)) { counts[l] = Object.keys(byLang[l]).length; }

return [{ json: {
  project_name: meta.project_name,
  project_id: meta.project_id,
  keys_total: meta.keys_total,
  base_lang: base,
  keys_scanned: keysScanned,
  candidates: candidates,
  detail_keys: detailKeys,
  filter_ok: (detailKeys <= candidates),
  counts: counts,
  distinct_keys_edited: Object.keys(allKeys).length,
  editors: editors,
  failed: failed,
  capped: capped
}}];

